const {cards,races,rarities,Game,starter}=Arcana;
const $=id=>document.getElementById(id);let deck=starter();try{let saved=JSON.parse(localStorage.getItem('arcana-deck'));if(Array.isArray(saved)&&saved.length===40&&saved.every(x=>Number.isInteger(x)&&cards[x])&&saved.every(x=>saved.filter(y=>y===x).length<=3))deck=saved}catch{}
let game=new Game(deck),selected=null,action=null,editing=false,draft=[...deck],view='battle',busy=false,generation=0,toastTimer;
const colors=['#ca9b65','#93b67c','#83c5c0','#aabec7','#ae8aab','#dfd5a0','#c78d9f','#6baebe','#bdc98c','#9cabe2'];
function art(c){let col=colors[c.raceId],n=c.id%10;let figure='';if(c.type==='spell'){figure=`<circle cx="90" cy="73" r="39" fill="none" stroke="${col}" stroke-width="2"/><circle cx="90" cy="73" r="29" fill="none" stroke="${col}" opacity=".45"/><path d="M90 22 L102 62 L139 73 L102 85 L90 126 L78 85 L41 73 L78 62Z" fill="${col}" opacity=".9"/><path d="M90 44 L98 73 L90 101 L82 73Z" fill="#eff8d2"/>`}
else if(c.type==='item'){figure=c.id%6===0?`<path d="M90 26L128 40L122 85Q114 112 90 125Q66 112 58 85L52 40Z" fill="#304947" stroke="${col}" stroke-width="3"/><path d="M90 40V105M68 61H112" stroke="${col}" stroke-width="5"/>`:`<path d="M112 18L120 38L79 98L68 91Z" fill="#bdd4c6" stroke="${col}" stroke-width="2"/><path d="M58 82L91 105" stroke="${col}" stroke-width="9"/><path d="M70 96L53 120" stroke="#99764c" stroke-width="8"/><circle cx="52" cy="123" r="7" fill="${col}"/>`}
else{let shapes=[`<path d="M84 102Q37 111 30 69L54 79L41 44L76 65L100 29L120 49L147 45L135 62L153 71L129 84L124 113Z" fill="#293e3c" stroke="${col}" stroke-width="2"/><path d="M102 49L98 18L115 37M70 73L52 27L85 56" fill="${col}"/><path d="M85 94L64 65L76 111L105 126L125 109" fill="${col}" opacity=".55"/><path d="M116 58L128 60" stroke="#fff3ba" stroke-width="3"/>`,`<path d="M55 57L49 23L78 45L104 44L131 22L124 61L138 91L110 121L71 125L43 92Z" fill="#2c4038" stroke="${col}" stroke-width="2"/><path d="M62 67L81 73L69 78M101 73L120 66L115 78" fill="#f2e9ac"/><path d="M90 84L104 94L90 112L76 94Z" fill="${col}"/><path d="M52 86L70 105M126 85L111 106" stroke="${col}" stroke-width="4"/>`,`<path d="M90 25Q60 32 65 70L46 120L132 120L114 71Q121 33 90 25Z" fill="#284447" stroke="${col}" stroke-width="2"/><path d="M90 37L73 68L90 89L107 68Z" fill="${col}" opacity=".65"/><ellipse cx="90" cy="65" rx="5" ry="11" fill="#eafbd7"/><path d="M68 82L35 53L45 103L67 112M113 82L145 53L136 103L114 113" fill="${col}" opacity=".6"/>`,`<path d="M64 40L116 40L127 80L112 97L117 124H62L68 97L53 80Z" fill="#30434a" stroke="${col}" stroke-width="3"/><path d="M73 28V42M108 28V42M67 56H114M70 90H110" stroke="${col}" stroke-width="4"/><circle cx="77" cy="67" r="5" fill="#efffc3"/><circle cx="103" cy="67" r="5" fill="#efffc3"/><path d="M51 71L34 108M129 71L146 108" stroke="${col}" stroke-width="13"/>`,`<path d="M52 122L66 89L61 53Q90 15 119 53L113 89L130 122Z" fill="#2d3742" stroke="${col}" stroke-width="2"/><path d="M73 51L108 51L112 82L90 97L69 81Z" fill="${col}" opacity=".7"/><path d="M73 64L85 68M98 68L109 63" stroke="#e4e6bf" stroke-width="4"/><path d="M87 81H98M80 89L77 118M103 88L107 119" stroke="#263a35" stroke-width="4"/>`,`<path d="M81 62Q27 28 29 50L43 97L75 104M100 62Q153 27 152 51L140 97L107 104" fill="${col}" opacity=".6"/><path d="M90 50L70 119H111Z" fill="#b8c6b2"/><circle cx="90" cy="47" r="14" fill="#e2d1ab"/><ellipse cx="90" cy="25" rx="21" ry="6" fill="none" stroke="${col}" stroke-width="3"/><path d="M45 58L74 91M136 58L106 91" stroke="#ecdeaa" stroke-width="2"/>`,`<path d="M68 56L48 21L78 38L101 38L131 20L113 58L131 123L48 123Z" fill="#3b2e40" stroke="${col}" stroke-width="2"/><path d="M73 65L85 69M99 69L110 64" stroke="#ffeeb9" stroke-width="4"/><path d="M83 79L91 87L99 79" fill="none" stroke="${col}" stroke-width="3"/><path d="M63 82L30 61L44 113L65 105M117 82L150 61L136 113L115 105" fill="${col}" opacity=".45"/>`,`<path d="M31 92Q60 44 108 61L136 40L132 75L156 90L127 97L116 117L96 105Q48 116 31 92Z" fill="#28464d" stroke="${col}" stroke-width="2"/><path d="M70 65L86 32L109 62M61 104L79 125L95 107" fill="${col}"/><circle cx="53" cy="83" r="4" fill="#f6e9ac"/><path d="M35 95L59 97" stroke="${col}" stroke-width="2"/>`,`<ellipse cx="65" cy="61" rx="24" ry="35" transform="rotate(-28 65 61)" fill="${col}" opacity=".5"/><ellipse cx="115" cy="61" rx="24" ry="35" transform="rotate(28 115 61)" fill="${col}" opacity=".5"/><path d="M90 58L70 113L112 113Z" fill="${col}"/><circle cx="90" cy="45" r="13" fill="#ead9ad"/><path d="M69 79L39 94M109 79L140 94" stroke="#d3dba9" stroke-width="3"/><path d="M141 74V113M131 84H151" stroke="#eff8b8" stroke-width="2"/>`,`<path d="M50 126L62 75L56 66L86 18L125 66L116 75L132 126Z" fill="#303c51" stroke="${col}" stroke-width="2"/><path d="M72 63L108 63L103 85L89 93L77 83Z" fill="#c5b990"/><path d="M62 75L87 112L116 75M86 111L84 130" fill="none" stroke="${col}" stroke-width="3"/><path d="M141 39V126" stroke="#bcb287" stroke-width="4"/><circle cx="141" cy="37" r="9" fill="${col}"/>`];figure=shapes[c.raceId]}
return `<svg viewBox="0 0 180 145" xmlns="http://www.w3.org/2000/svg"><defs><radialGradient id="g${c.id}"><stop stop-color="${col}" stop-opacity=".38"/><stop offset="1" stop-color="#0e1c20"/></radialGradient></defs><rect width="180" height="145" fill="url(#g${c.id})"/><circle cx="90" cy="77" r="54" fill="none" stroke="${col}" opacity=".18"/><path d="M5 125L42 93L65 132L95 99L134 126L168 85L180 132V145H0Z" fill="#09191b" opacity=".6"/>${figure}<g fill="${col}" opacity=".55"><circle cx="24" cy="35" r="1"/><circle cx="148" cy="25" r="1.5"/><circle cx="150" cy="112" r="1"/><circle cx="41" cy="118" r="1.5"/><circle cx="121" cy="16" r="1"/></g></svg>`}
const rareCodes=['N','R','SR','HR','UR'];
function cardHTML(c,u=null,p=null){let power=u?game.power(u,p):c.power;return `<div class="card-art" style="--glow:${colors[c.raceId]}">${art(c)}<span class="card-cost">${c.cost}</span><span class="card-race">${c.race}</span>${u?`<span class="unit-state">${u.items.length?'装備 '+u.items.length+' · ':''}${u.sleep&&!game.has(u,'haste')?'召喚酔い':game.canAttack(u)?'攻撃可能':'行動済み'}</span>`:''}</div><div class="card-name">${c.name}</div><div class="card-text">${c.text}</div><div class="card-foot"><span>${rareCodes[c.rarity]} · ${c.type==='monster'?'MONSTER':c.type==='spell'?'SPELL':'ITEM'}</span>${c.type==='monster'?`<b>⚔ ${power}</b>`:'<b>✧</b>'}</div>`}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3000)}
function viewSide(){return game.mode==='local'?game.turn:0}
function allowed(){return game.winner===null&&!game.pending&&!busy&&(game.mode==='local'||game.turn===0)}
function render(){let me=viewSide(),p=game.players[me],e=game.players[1-me];$('enemyName').textContent=game.mode==='local'?`PLAYER ${2-me}`:'NOCTIS';$('enemyLabel').textContent=game.mode==='local'?'LOCAL / 対戦相手':'CPU / 深淵の召喚士';$('youName').textContent=game.mode==='local'?`PLAYER ${me+1}`:'YOU';for(let [name,q]of[['your',p],['enemy',e]]){$(name+'Hp').textContent=Math.max(0,q.hp).toLocaleString();$(name+'HpBar').style.width=Math.max(0,Math.min(100,q.hp/4000*100))+'%';$(name+'Energy').innerHTML=`<small>ENERGY</small><strong>✧ ${q.energy}</strong><span> / ${q.max}</span>`;$(name+'Deck').innerHTML=`▱ ${q.deck.length}<small>DECK · 墓地 ${q.grave.length}</small>`}
$('enemyHand').innerHTML=e.hand.map(()=>'<div class="cardback">✧</div>').join('');$('handCount').textContent=p.hand.length+' CARDS';$('turnLabel').textContent='TURN '+String(game.round).padStart(2,'0');$('phaseLabel').textContent=game.turn===me?'YOUR TURN':'ENEMY TURN';$('phaseLabel').style.color=game.turn===me?'#8bd4bd':'#d59db1';$('statusTitle').textContent=game.pending?'ブロックを選択':busy?'相手が思考中…':game.turn===me?'あなたのターン':'相手のターン';$('statusText').textContent=action?(action.type==='attack'?'相手の体力かモンスターを選択。':'光っている対象を選択。'):game.pending?'ブロッカーで攻撃を引き受けますか？':'カードを選んで、戦場へ。';$('endTurn').disabled=!allowed()||!!action;$('logs').innerHTML=game.log.map(x=>`<p>${x}</p>`).join('');
for(let [id,q,side]of[['playerField',p,me],['enemyField',e,1-me]]){let el=$(id);el.replaceChildren();q.field.forEach(u=>{let b=document.createElement('button');b.className=`card r${u.card.rarity} ${game.canAttack(u)?'ready':'tapped'} ${selected?.uid===u.uid?'selected':''}`;b.innerHTML=cardHTML(u.card,u,q);b.setAttribute('aria-label',u.card.name+' パワー'+game.power(u,q));if(isTarget(side,u.uid))b.classList.add('targetable');b.onclick=()=>unitClick(side,u);el.append(b)});for(let i=q.field.length;i<6;i++){let a=document.createElement('div');a.className='slot';a.textContent='✧';el.append(a)}}
$('enemyHp').parentElement.classList.toggle('targetable',!!action&&(action.type==='attack'||action.need==='enemyAny'));$('hand').replaceChildren();(game.mode==='local'&&game.pending?[]:p.hand).forEach((id,i)=>{let c=cards[id],b=document.createElement('button');b.className=`card r${c.rarity} ${c.cost>p.energy?'unaffordable':''} ${selected?.hand===i?'selected':''}`;b.innerHTML=cardHTML(c);b.setAttribute('aria-label',`${c.name} コスト${c.cost}`);b.onclick=()=>{if(!allowed())return;action=null;selected={hand:i,card:c};render()};$('hand').append(b)});renderInspect();
if(game.winner!==null){$('result').innerHTML=`<div class="eyebrow">THE DUEL HAS ENDED</div><h2>${game.winner===me?'VICTORY':'DEFEAT'}</h2><p>${game.players[1-game.winner].hp<=0?'体力が0になりました。':'デッキが0枚になりました。'} ${game.mode==='local'?`PLAYER ${game.winner+1} の勝利。`:game.winner===0?'あなたの勝利です。':'NOCTIS の勝利です。'}</p><button class="gold-button" id="again">もう一度対戦する →</button>`;$('again').onclick=newGame}else $('result').innerHTML='';}
function isTarget(side,id){if(game.pending)return game.pending.defender===side&&game.players[side].field.some(u=>u.uid===id&&game.canBlock(u));if(!action)return false;return action.type==='attack'?side!==game.turn:action.need==='ally'?side===game.turn:side!==game.turn}
function renderInspect(){let el=$('inspect');if(game.pending&&game.pending.defender===viewSide()){el.innerHTML='<div class="eyebrow">DEFENSE RESPONSE</div><h3>攻撃が迫っています</h3><div class="desc">光っているブロッカーを選ぶと、そのモンスターが攻撃を引き受けます。</div><button class="gold-button" id="passBlock">ブロックしない</button>';$('passBlock').onclick=()=>{game.block(null);render()};return}if(!selected){el.innerHTML='<div class="eyebrow">CARD INFORMATION</div><div class="empty-inspect">✧</div><p>カードを選ぶと<br>詳細とアクションを表示します。</p>';return}let c=selected.card;el.innerHTML=`<div class="eyebrow">${c.type.toUpperCase()} / ${rareCodes[c.rarity]}</div><h3>${c.name}</h3><div class="inspect-meta">${c.race} · コスト ${c.cost} · ${rarities[c.rarity]}</div><div class="desc">${c.text}</div>`;if(action){el.innerHTML+='<button class="quiet" id="cancel">対象選択をキャンセル</button>';$('cancel').onclick=()=>{action=null;render()};return}
if(selected.hand!==undefined){let valid=allowed()&&c.cost<=game.active.energy;el.innerHTML+=`<button id="use" class="gold-button" ${valid?'':'disabled'}>${c.type==='monster'?'モンスターを召喚':c.type==='spell'?'魔法を使用':'アイテムを装備'} <span>→</span></button>`;if(!valid)el.innerHTML+='<div class="shortcuts">エネルギーが足りません</div>';$('use').onclick=useCard}
else if(selected.side===game.turn){let u=game.active.field.find(x=>x.uid===selected.uid);if(u){el.innerHTML+=`<button id="attack" class="gold-button" ${allowed()&&game.canAttack(u)?'':'disabled'}>攻撃する <span>⚔</span></button>`;$('attack').onclick=()=>{action={type:'attack',uid:u.uid};render()}}}}
function useCard(){let i=selected.hand,r=game.play(i);if(r&&r.target){action={type:'play',index:i,need:r.target};render();toast('光っている対象を選んでください')}else if(r){selected=null;render()}else toast('今は使用できません。対象・場の上限・エネルギーを確認してください。')}
function unitClick(side,u){if(game.pending){if(side===game.pending.defender&&game.canBlock(u)){game.block(u.uid);render()}return}if(action){if(!isTarget(side,u.uid))return;executeTarget(side,u.uid);return}selected={uid:u.uid,side,card:u.card};render()}
function executeTarget(side,uid){let r=action.type==='attack'?game.attack(action.uid,uid):game.play(action.index,{side,uid});if(!r){toast('この対象には使用できません');return}action=null;selected=null;render();if(game.pending){if(game.mode==='cpu'&&game.pending.defender===1){let b=game.enemy.field.find(x=>game.canBlock(x));game.block(b?b.uid:null);render()}else if(game.mode==='local')handoff('防御プレイヤーに交代',()=>{renderDefense()})}}
function renderDefense(){render();let p=game.pending;if(!p)return;let el=$('inspect');el.innerHTML='<div class="eyebrow">DEFENSE RESPONSE</div><h3>ブロックを選択</h3><div class="desc">光っているブロッカーを選択。ブロックすると行動済みになります。</div><button class="gold-button" id="passBlock">ブロックしない</button>';$('passBlock').onclick=()=>{game.block(null);render()}}
$('enemyHp').parentElement.onclick=()=>{if(action&&(action.type==='attack'||action.need==='enemyAny'))executeTarget(1-game.turn,null)};
$('endTurn').onclick=()=>{if(!allowed())return;selected=null;action=null;if(game.mode==='local'){$('hand').replaceChildren();handoff(`PLAYER ${2-game.turn} に交代`,()=>{game.endTurn();render()})}else{game.endTurn();render();runAI()}};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function runAI(){let token=generation;busy=true;render();await sleep(650);for(let steps=0;steps<30;steps++){if(token!==generation)return;if(game.winner!==null||game.turn!==1)break;if(game.pending){await sleep(250);steps--;continue}let did=false;let order=game.active.hand.map((id,i)=>({c:cards[id],i})).sort((a,b)=>((a.c.type==='monster'?8:0)-a.c.cost)-((b.c.type==='monster'?8:0)-b.c.cost)).reverse();for(let {c,i}of order){if(c.cost>game.active.energy)continue;let result=game.play(i);if(result?.target){let t=result.target;if(t==='ally'){let u=[...game.active.field].sort((a,b)=>game.power(b,game.active)-game.power(a,game.active))[0];if(u)result=game.play(i,{side:1,uid:u.uid});else result=false}else if(t==='enemyAny')result=game.play(i,{side:0,uid:null});else{let units=game.enemy.field.filter(u=>c.effect!==5||game.power(u,game.enemy)<=800+c.rarity*300);result=units.length?game.play(i,{side:0,uid:units[0].uid}):false}}if(result===true){did=true;render();await sleep(550);break}}if(!did)break}
for(let guard=0;guard<20&&token===generation&&game.winner===null;guard++){if(game.pending){await sleep(250);guard--;continue}let u=game.active.field.find(x=>game.canAttack(x));if(!u)break;let weakest=[...game.enemy.field].sort((a,b)=>game.power(a,game.enemy)-game.power(b,game.enemy))[0];let target=weakest&&game.power(weakest,game.enemy)<=game.power(u,game.active)&&game.enemy.hp>game.power(u,game.active)?weakest.uid:null;game.attack(u.uid,target);render();await sleep(650)}
while(game.pending&&token===generation){await sleep(200)}if(token!==generation)return;busy=false;if(game.winner===null)game.endTurn();render()}
function newGame(){generation++;busy=false;selected=null;action=null;game=new Game(deck,$('mode').value);render();toast('対戦開始。先攻のあなたからスタート！')}
$('restart').onclick=()=>{showModal('<h2>新しい対戦</h2><p>進行中の対戦を終了し、選択したモードで最初から始めます。</p><button class="gold-button" id="confirmNew">対戦を開始</button>');$('confirmNew').onclick=()=>{$('modal').close();newGame()}};$('mode').onchange=()=>toast('「新しい対戦」から選択したモードを開始できます');
function handoff(t,cb){showModal(`<div class="handoff"><div class="eyebrow">LOCAL MULTIPLAYER</div><h2>${t}</h2><p>画面を相手に渡したら、準備完了を押してください。</p><button id="ready" class="gold-button">準備完了 →</button></div>`);$('closeModal').hidden=true;$('modal').onkeydown=e=>{if(e.key==='Escape')e.preventDefault()};$('ready').onclick=()=>{$('closeModal').hidden=false;$('modal').onkeydown=null;$('modal').close();cb()}}
function showModal(html){$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
$('closeModal').onclick=()=>$('modal').close();$('modal').addEventListener('click',e=>{if(e.target===$('modal')&&!$('closeModal').hidden)$('modal').close()});
$('rulesBtn').onclick=()=>showModal(`<div class="eyebrow">HOW TO PLAY</div><h2>アルカナ・デュエルの遊び方</h2><p>40枚のデッキ、初期手札6枚、エネルギー0、体力4000。相手の体力を0にするか、相手のデッキを0枚にすれば勝利です。</p><ol><li>ターン開始時にエネルギー総量＋1、全回復し、1枚引きます。先攻の最初のターンも引くため、開始画面では手札7枚・エネルギー1です。</li><li>手札を選び、詳細欄からコストを払って使用。モンスターは最大6体。魔法は即座に効果を発揮し、アイテムは味方に装備できます。装備数の上限はありません。</li><li>自分のモンスターを選んで「攻撃する」を押し、相手の体力か敵モンスターを選択。敵がいても直接攻撃できます。通常は召喚したターンには攻撃できません。</li><li>戦闘ではパワーが高い方が生き残り、低い方が破壊されます。同値は相打ち。直接攻撃はパワー分のダメージです。</li><li>未行動で召喚酔いしていないブロッカーは、攻撃1回を自身に誘導し、行動済みになります。自分のターン開始時に未行動へ戻ります。</li><li>「ターン終了」で交代。手札・体力・エネルギー総量に上限はありません。ダメージ魔法で減ったパワーは永続します。戦意・進軍による強化も永続です。</li></ol><p>図鑑：モンスター100種（10種族）・魔法50種・アイテム30種。N → R → SR → HR → UR。デッキは40枚、同名カードは3枚まで。編集内容はこのブラウザーに保存され、次の対戦に反映されます。</p><p>CPU対戦 / 2人交代対戦を選べます。2人交代対戦は同じ画面を使います。通信対戦には対応していません。</p>`);
function showView(v){view=v;editing=v==='deck';$('battle').hidden=v!=='battle';$('collection').hidden=v==='battle';for(let [id,k]of[['battleTab','battle'],['collectionTab','collection'],['deckTab','deck']])$(id).classList.toggle('active',k===v);if(v!=='battle'){$('libraryTitle').textContent=editing?'あなたのデッキを編成':'カード図鑑';$('saveDeck').hidden=!editing;$('resetDeck').hidden=!editing;$('archiveHint').textContent=editing?'＋ / − でカードを入れ替え。40枚・同名3枚まで。保存後、次の対戦から使用されます。':'全180種類。カードをクリックして能力やパワーを確認できます。';renderCatalog()}}
$('battleTab').onclick=()=>showView('battle');$('collectionTab').onclick=()=>showView('collection');$('deckTab').onclick=()=>showView('deck');
races.forEach((r,i)=>$('raceFilter').add(new Option(r,i)));rarities.forEach((r,i)=>$('rarityFilter').add(new Option(r,i)));for(let id of ['search','typeFilter','raceFilter','rarityFilter'])$(id).oninput=renderCatalog;
function renderCatalog(){let s=$('search').value.trim(),type=$('typeFilter').value,race=$('raceFilter').value,rare=$('rarityFilter').value;let list=cards.filter(c=>(!s||(c.name+c.text+c.race).includes(s))&&(type==='all'||c.type===type)&&(race==='all'||c.type==='monster'&&c.raceId===+race)&&(rare==='all'||c.rarity===+rare));$('deckCount').textContent=editing?`編成 ${draft.length} / 40 枚`:`${list.length} 枚`;$('saveDeck').disabled=draft.length!==40;$('catalog').replaceChildren();list.forEach(c=>{let wrap=document.createElement('div'),b=document.createElement('button');b.className=`card r${c.rarity}`;b.innerHTML=cardHTML(c);b.onclick=()=>showModal(`<div class="card r${c.rarity} modal-card">${cardHTML(c)}</div><div class="inspect-meta">${rarities[c.rarity]} / ${c.race} / コスト ${c.cost}</div><p>${c.text}</p>`);wrap.append(b);if(editing){let controls=document.createElement('div'),num=draft.filter(x=>x===c.id).length;controls.className='deck-add';controls.innerHTML=`<button aria-label="${c.name}を減らす" ${!num?'disabled':''}>−</button><span>${num} 枚</span><button aria-label="${c.name}を追加" ${num>=3||draft.length>=40?'disabled':''}>＋</button>`;controls.firstElementChild.onclick=()=>{draft.splice(draft.indexOf(c.id),1);renderCatalog()};controls.lastElementChild.onclick=()=>{draft.push(c.id);renderCatalog()};wrap.append(controls)}$('catalog').append(wrap)})}
$('saveDeck').onclick=()=>{if(draft.length!==40)return;deck=[...draft];try{localStorage.setItem('arcana-deck',JSON.stringify(deck));toast('デッキを保存しました。次の対戦から使えます。')}catch{toast('この環境では保存できません。この画面を開いている間は使用できます。')}};$('resetDeck').onclick=()=>{draft=starter();renderCatalog();toast('編成を初期状態に戻しました。保存すると反映されます。')};render();
